WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_txn_time FROM transactions), gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END AS session_start_flag_tier, CASE WHEN amount >= 3100 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, APPROX_PERCENTILE(amount, 0.95) AS amount_p95, ROUND(AVG(session_start_flag), 2) AS avg_session_start_flag, APPROX_PERCENTILE(amount, 0.95) AS amount_p95_2, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, MAX(session_start_flag) FILTER (WHERE txn_type = 'DEBIT') AS debit_max_session_start_flag FROM islands GROUP BY CUBE (CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN amount >= 3100 THEN 'HIGH' ELSE 'LOW' END) ORDER BY avg_session_start_flag DESC;
